#ifndef SCAMP_IMAGE_IO_HPP
#define SCAMP_IMAGE_IO_HPP

#include "image.hpp"
#include <iostream>
#include <iomanip>
#include <sstream>
#include <stdexcept>

inline uint64_t hex64(const std::string& s) { return std::stoull(s, nullptr, 16); }

inline ip6_t read_ip() {
    std::string a, b;
    std::cin >> a >> b;
    return {hex64(a), hex64(b)};
}

inline void image_write_json(const ImageData& d) {
    auto loc = [](ImageLoc x) { std::cout << '[' << x.stage << ',' << x.cell << ']'; };
    auto fronts = [&](const std::vector<ImageFront>& v, int width) {
        std::cout << '[';
        bool first = true;
        for (size_t i = 0; i < v.size(); ++i) {
            const ImageFront& e = v[i];
            if (!first) std::cout << ',';
            first = false;
            std::ostringstream key;
            key << std::hex << std::setfill('0') << std::setw(width) << e.key;
            std::cout << "[\"" << key.str() << "\"," << e.loc.stage << ',' << e.loc.cell << ']';
        }
        std::cout << ']';
    };
    std::cout << "{\"root\":";
    if (d.root.stage < 0) std::cout << "null";
    else loc(d.root);
    std::cout << ",\"front16\":";
    fronts(d.front16, 4);
    std::cout << ",\"front64\":";
    fronts(d.front64, 16);
    std::cout << ",\"cells\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) std::cout << ',';
        std::cout << d.cells[s];
    }
    std::cout << "],\"banks\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) std::cout << ',';
        std::cout << '[';
        bool first = true;
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (!first) std::cout << ',';
            first = false;
            std::cout << '"' << image_word_hex(d.banks[s][i]) << '"';
        }
        std::cout << ']';
    }
    std::cout << "],\"bitmaps\":[";
    for (size_t i = 0; i < d.bitmaps.size(); ++i) {
        if (i) std::cout << ',';
        std::ostringstream mask;
        mask << std::hex << std::setfill('0') << std::setw(16) << d.bitmaps[i];
        std::cout << '"' << mask.str() << '"';
    }
    std::cout << "],\"nexthops\":[";
    for (size_t i = 0; i < d.nexthops.size(); ++i) {
        if (i) std::cout << ',';
        std::cout << d.nexthops[i];
    }
    std::cout << "]}";
}

inline ImageData image_read_wire() {
    ImageData d;
    std::cin >> d.root.stage >> d.root.cell;
    std::vector<ImageFront>* vs[2] = { &d.front16, &d.front64 };
    for (int f = 0; f < 2; ++f) {
        std::vector<ImageFront>& v = *vs[f];
        size_t n;
        std::cin >> n;
        v.resize(n);
        for (size_t i = 0; i < n; ++i) {
            std::string key;
            std::cin >> key >> v[i].loc.stage >> v[i].loc.cell;
            v[i].key = hex64(key);
        }
    }
    for (int s = 0; s < RAM_NUM; ++s) std::cin >> d.cells[s];
    for (int s = 0; s < RAM_NUM; ++s) {
        size_t n;
        std::cin >> n;
        d.banks[s].resize(n);
        for (size_t i = 0; i < n; ++i) {
            std::string text;
            std::cin >> text;
            d.banks[s][i] = image_word_from_hex(text);
        }
    }
    size_t n;
    std::cin >> n;
    d.bitmaps.resize(n);
    for (size_t i = 0; i < n; ++i) {
        std::string text;
        std::cin >> text;
        d.bitmaps[i] = hex64(text);
    }
    std::cin >> n;
    d.nexthops.resize(n);
    for (size_t i = 0; i < n; ++i) std::cin >> d.nexthops[i];
    if (!std::cin) throw std::runtime_error("wire input");
    return d;
}

#endif
