#include "capture.hpp"
#include "fib.h"
#include "image_io.hpp"

#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <vector>
#include <sys/wait.h>

int main() {
    try {
        std::ios::sync_with_stdio(false);
        std::cin.tie(nullptr);
        size_t cases;
        std::cin >> cases;
        std::cout << "{\"results\":[";
        for (size_t c = 0; c < cases; ++c) {
            if (c) std::cout << ',';
            LiveFib live;
            MemoryImage loaded;
            std::vector<nexthop_t> answers;
            std::vector<ImageData> saved;
            std::vector<char> loads;
            size_t count;
            std::cin >> count;
            for (size_t i = 0; i < count; ++i) {
                char op;
                std::cin >> op;
                if (op == 'P') {
                    ip6_t ip = read_ip();
                    unsigned len;
                    uint64_t hop;
                    std::cin >> len >> hop;
                    live.put(ip, (int)len, (nexthop_t)hop);
                } else if (op == 'Q' || op == 'I') {
                    size_t n;
                    std::cin >> n;
                    for (size_t j = 0; j < n; ++j) {
                        ip6_t ip = read_ip();
                        answers.push_back(op == 'Q' ? live.query(ip) : loaded.lookup(ip));
                    }
                } else if (op == 'S') {
                    saved.push_back(capture_image(live.routes()));
                } else if (op == 'R') {
                    size_t id;
                    std::cin >> id;
                    loads.push_back(loaded.load(saved.at(id)) ? 1 : 0);
                } else if (op == 'L') {
                    ImageData d = image_read_wire();
                    loads.push_back(loaded.load(d) ? 1 : 0);
                } else {
                    throw std::runtime_error("wire opcode");
                }
            }
            if (!std::cin) throw std::runtime_error("wire exhausted");
            std::cout << "{\"answers\":[";
            for (size_t i = 0; i < answers.size(); ++i) {
                if (i) std::cout << ',';
                if (answers[i] == LPM_INVALID_NH) std::cout << "null";
                else std::cout << answers[i];
            }
            std::cout << "],\"snapshots\":[";
            for (size_t i = 0; i < saved.size(); ++i) {
                if (i) std::cout << ',';
                image_write_json(saved[i]);
            }
            std::cout << "],\"loads\":[";
            for (size_t i = 0; i < loads.size(); ++i) {
                if (i) std::cout << ',';
                std::cout << (loads[i] ? "true" : "false");
            }
            std::cout << "]}";
        }
        std::cout << "]}\n";
        if (const char* feed = std::getenv("SCAMP_FEED_PID")) {
            int status;
            waitpid(std::strtol(feed, nullptr, 10), &status, 0);
        }
        return 0;
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}
